#include "../Source/Plugins/ReferenceMatchProcessor.h"
#include "../Source/SessionState.h"
#include "../Source/Systems/PresetManager.h"
#include "../Source/Systems/OfflineMixRenderer.h"
#include <random>
#include <cstdio>
#include <cstdlib>
void check(bool ok,const char* what){if(!ok){std::fprintf(stderr,"FAIL %s\n",what);std::exit(1);}}
int main(){juce::ScopedJuceInitialiser_GUI juce;
 hem::ReferenceMatchProcessor p;hem::ReferenceMatchProcessor::Snapshot snap;
 check(p.captureSnapshot(snap).wasOk(),"empty capture");juce::ValueTree encoded;check(p.encodeSnapshot(snap,encoded).wasOk(),"empty encode");hem::ReferenceMatchProcessor::Snapshot decoded;check(p.decodeSnapshot(encoded,decoded).wasOk(),"empty decode");
 std::vector<float> x(48000),y(48000);std::mt19937 rng(1);for(size_t i=0;i<x.size();++i){x[i]=float(int(rng()%20000)-10000)/50000;y[i]=x[i]*.4f+(i?y[i-1]*.6f:0);}
 const float* source[]={x.data()};const float* ref[]={y.data()};auto profile=hem::reference_match::analyze(source,1,x.size(),48000);
 check(p.setSourceUnpublished(profile).wasOk(),"source");check(p.captureSnapshot(snap).failed(),"uncommitted editing rejected");check(p.setReferenceUnpublished(ref,1,y.size(),48000).wasOk(),"reference");check(p.matchUnpublished().wasOk(),"match");check(p.captureSnapshot(snap).wasOk(),"committed capture");check(p.encodeSnapshot(snap,encoded).wasOk(),"encode committed");check(p.decodeSnapshot(encoded,decoded).wasOk(),"decode committed");
 hem::ReferenceMatchProcessor restored;check(restored.restoreSnapshotUnpublished(decoded,48000).wasOk(),"restore private");juce::MemoryBlock binary;p.getStateInformation(binary);check(binary.getSize()>1000,"binary contains profile");
 auto broken=encoded.createCopy();broken.getChildWithName("SOURCE").getChild(0).setProperty("power",-1,nullptr);check(p.decodeSnapshot(broken,decoded).failed(),"negative profile rejected");
 check(p.setReferenceUnpublished(source,1,x.size(),48000).wasOk(),"second reference");check(p.matchUnpublished().wasOk(),"second match");check(p.revertUnpublished().wasOk(),"rollback");check(p.captureSnapshot(snap).wasOk()&&!snap.previous,"rollback consumed");check(std::abs(snap.reference.power[40]-profile.power[40])>1e-10,"rollback restored prior reference");
 p.markPublished();check(p.matchUnpublished().failed(),"live match rejected");check(p.restoreSnapshotUnpublished(snap,48000).failed(),"live restore rejected");
 restored.prepareToPlay(48000,256);juce::MidiBuffer midi;juce::AudioBuffer<float> block(2,256);block.clear();restored.processBlock(block,midi);
 restored.state.getParameter("matchAmount")->setValueNotifyingHost(.4f);check(restored.captureSnapshot(snap).failed(),"refit pending blocks capture");
 bool settled=false;for(int i=0;i<500&&!settled;++i){restored.processBlock(block,midi);juce::Thread::sleep(2);settled=restored.captureSnapshot(snap).wasOk();}check(settled,"worker refit publishes and settles");
 check(restored.startSourceCapture(),"capture arm");check(!restored.startSourceCapture(),"duplicate capture rejected");check(restored.captureSnapshot(snap).failed(),"capture pending blocks save");
 juce::AudioBuffer<float> capture(2,480000);for(int ch=0;ch<2;++ch)for(int i=0;i<capture.getNumSamples();++i)capture.setSample(ch,i,x[size_t(i)%x.size()]);restored.processBlock(capture,midi);
 hem::reference_match::Profile measured;bool done=false;for(int i=0;i<500&&!done;++i){juce::Thread::sleep(2);done=restored.takeCapturedProfile(measured);}check(done&&measured.status==hem::reference_match::Status::ready,"bounded pre-match capture analyzed");
 check(restored.startSourceCapture(),"second capture");restored.sourceTimeline(0);restored.processBlock(block,midi);restored.sourceTimeline(99999);restored.processBlock(block,midi);done=false;for(int i=0;i<500&&!done;++i){juce::Thread::sleep(2);done=restored.takeCapturedProfile(measured);}check(done&&measured.status==hem::reference_match::Status::discontinuity,"timeline gap invalidates capture");
 check(restored.startSourceCapture(),"capture before stop");restored.cancelCaptureWhileCallbackExcluded();check(!restored.captureInProgress(),"stopped graph cancel releases capture");
 auto hostile=encoded.createCopy();hostile.setProperty("previousAmount","garbage",nullptr);check(p.decodeSnapshot(hostile,decoded).failed(),"hostile numeric rejected");
 hem::NativeProcessorSnapshot whole;check(hem::NativeProcessorState::capture(p,whole).wasOk(),"whole state capture");auto clone=hem::NativeProcessorState::deepCopy(whole);clone.matchProfile->setProperty("previousAmount",.3,nullptr);check(double((*whole.matchProfile)["previousAmount"])!=.3,"profile deep copy");
 hem::MonitorProcessor monitor;hem::SessionSnapshot session;session.monitorParameters=hem::SessionState::captureParameters(monitor);auto& slot=session.tracks[0].slots[0];static_cast<hem::NativeProcessorSnapshot&>(slot)=whole;slot.pluginId="reference-match";
 auto destination=juce::File::getCurrentWorkingDirectory().getChildFile("reference-session.xml");auto sessionTree=hem::SessionState::encode(session,destination);check(int(sessionTree["version"])==4,"version4 match");auto roundtrip=hem::SessionState::decode(sessionTree,destination);check(roundtrip.tracks[0].slots[0].matchProfile.has_value(),"session profile roundtrip");
 hem::SessionState::save(session,destination);auto xmlSession=hem::SessionState::load(destination);hem::ReferenceMatchProcessor::Snapshot xmlProfile;check(p.decodeSnapshot(*xmlSession.tracks[0].slots[0].matchProfile,xmlProfile).wasOk(),"xml profile decode");check(xmlProfile.reference.power==snap.reference.power,"exact XML spectrum");
 auto json=destination.withFileExtension("json");hem::PresetManager::save(session,json);auto jsonSession=hem::PresetManager::load(json);check(jsonSession.tracks[0].slots[0].matchProfile.has_value(),"JSON profile roundtrip");
 hem::OfflineMixOptions tailOptions;tailOptions.sampleRate=96000;tailOptions.tailSeconds=0;check(hem::OfflineMixRenderer::preflightTail(session,tailOptions).failed(),"captured Reference tail refuses truncation");tailOptions.tailSeconds=60;check(hem::OfflineMixRenderer::preflightTail(session,tailOptions).wasOk(),"captured Reference tail permits conservative duration");tailOptions.tailSeconds=0;tailOptions.allowTailTruncation=true;check(hem::OfflineMixRenderer::preflightTail(session,tailOptions).wasOk(),"explicit tail truncation opt-in");
 hem::SessionSnapshot legacy;legacy.monitorParameters=session.monitorParameters;check(int(hem::SessionState::encode(legacy,destination)["version"])==1,"legacy version unchanged");
 auto badWhole=whole;badWhole.parameters=whole.parameters.createCopy();badWhole.parameters.getChildWithProperty("id","matchAmount").setProperty("value",.321,nullptr);check(hem::NativeProcessorState::validate(p,badWhole).failed(),"duplicate scalar mismatch");
 std::unique_ptr<hem::ModuleProcessor> privateCopy;hem::NativeRestoreContext context;context.sampleRate=48000;context.blockSize=256;check(hem::NativeProcessorState::restoreUnpublished(std::make_unique<hem::ReferenceMatchProcessor>(),whole,context,privateCopy).wasOk(),"private export restore");privateCopy->prepareToPlay(48000,256);check(hem::NativeProcessorState::validatePreparedForPublication(*privateCopy).wasOk(),"private export prepared");
 auto wav=destination.getSiblingFile("reference-fixture.wav");wav.deleteFile();juce::WavAudioFormat format;auto stream=wav.createOutputStream();check(bool(stream),"fixture stream");std::unique_ptr<juce::AudioFormatWriter> writer(format.createWriterFor(stream.get(),48000,1,24,{},0));check(bool(writer),"fixture writer");stream.release();check(writer->writeFromFloatArrays(ref,1,int(y.size())),"fixture write");writer.reset();
 hem::ReferenceMatchProcessor fileProcessor;check(fileProcessor.loadReferenceFileUnpublished(wav).wasOk(),"reference file load");check(fileProcessor.referenceIdentityOffThread().sha256.length()==64,"reference identity");check(fileProcessor.setSourceUnpublished(profile).wasOk()&&fileProcessor.matchUnpublished().wasOk(),"file match");hem::NativeProcessorSnapshot fileState;check(hem::NativeProcessorState::capture(fileProcessor,fileState).wasOk(),"file capture");
 {auto mutation=wav.createOutputStream();check(bool(mutation),"fixture mutation");mutation->setPosition(wav.getSize()-1);mutation->writeByte(77);}
 hem::ReferenceMatchProcessor changed;check(changed.restoreNativeStateOffThread(fileState,context).wasOk(),"changed reference retains committed fit");check(changed.matchUnpublished().failed(),"changed reference rematch rejected");
 juce::MemoryBlock binaryWhole;check(hem::NativeProcessorState::encodeBinary(p,whole,binaryWhole).wasOk(),"native binary encode");auto text=juce::String::fromUTF8(static_cast<const char*>(binaryWhole.getData()),int(binaryWhole.getSize()));text=text.replaceFirstOccurrenceOf("version=\"1\"","version=\"1\" version=\"1\"");hem::NativeProcessorSnapshot rejected;check(hem::NativeProcessorState::decodeBinary(p,text.toRawUTF8(),text.getNumBytesAsUTF8(),rejected).failed(),"duplicate XML rejected before parse");
 auto injected=whole;injected.matchProfile=whole.matchProfile->createCopy();check(hem::NativeProcessorState::validate(monitor,injected).failed(),"nonreference profile rejected");
 int auditions=0;p.editorActions.audition=[&](bool){++auditions;};{std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());check(editor->findChildWithID("matchAmount")!=nullptr&&editor->findChildWithID("captureSource")!=nullptr,"approved controls reachable");auto image=editor->createComponentSnapshot(editor->getLocalBounds());auto png=destination.getSiblingFile("reference-editor.png").createOutputStream();juce::PNGImageFormat pngFormat;check(png&&pngFormat.writeImageToStream(image,*png),"editor render");}check(auditions==1,"editor close returns source audition");
 std::puts("PASS ReferenceMatchStateTests");}
